mapper.sql:
PR.ROLE_TYPE_ID IN (
    SELECT WET.ORG_UNIT_ROLE_TYPE_ID
    FROM WORK_EFFORT_TYPE WET
    WHERE WET.WORK_EFFORT_TYPE_ID = #{workEffortTypeId, jdbcType=VARCHAR}
)
OR (
        PR.ROLE_TYPE_ID IN (
            SELECT WET.ORG_UNIT_ROLE_TYPE_ID2
            FROM WORK_EFFORT_TYPE WET
            WHERE WET.WORK_EFFORT_TYPE_ID = #{workEffortTypeId, jdbcType=VARCHAR}
        )
        OR PR.ROLE_TYPE_ID IN (
            SELECT WET.ORG_UNIT_ROLE_TYPE_ID3
            FROM WORK_EFFORT_TYPE WET
            WHERE WET.WORK_EFFORT_TYPE_ID = #{workEffortTypeId, jdbcType=VARCHAR}
        )
)

mapper.select:
SELECT P.*
 FROM PARTY P
 WHERE P.PARTY_ID = #{organizationId}
